export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import {test} from 'node:test';
import {taskLabel} from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('deploy service', true), '[x] deploy service');
});

test('incomplete task retains [ ] prefix', () => {
  assert.equal(taskLabel('write documentation', false), '[ ] write documentation');
});

test('preserves exact name including spaces and special characters', () => {
  assert.equal(taskLabel('  trimmed? no!  ', true), '[x]   trimmed? no!  ');
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('task [1]', true), '[x] task [1]');
});

